class ContractFailure(Exception):
    pass


class DuplicateKeyLoader(yaml.SafeLoader):
    pass


def _construct_mapping(loader: DuplicateKeyLoader, node: yaml.MappingNode, deep: bool = False) -> dict[Any, Any]:
    result: dict[Any, Any] = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if key in result:
            raise ContractFailure(f"DUPLICATE_KEY:{key}")
        result[key] = loader.construct_object(value_node, deep=deep)
    return result


DuplicateKeyLoader.add_constructor(
    yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,
    _construct_mapping,
)


def reject_duplicate_json_object(
    pairs: list[tuple[str, Any]],
) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ContractFailure(f"DUPLICATE_JSON_KEY:{key}")
        result[key] = value
    return result


def load_json(path: Path) -> Any:
    return json.loads(
        path.read_text(encoding="utf-8"),
        object_pairs_hook=reject_duplicate_json_object,
    )


def load_yaml(path: Path) -> Any:
    return yaml.load(path.read_text(encoding="utf-8"), Loader=DuplicateKeyLoader)


def canonical_bytes(value: Any) -> bytes:
    return rfc8785.dumps(value)


def digest(value: dict[str, Any]) -> str:
    unsigned = {key: val for key, val in value.items() if key != "digest"}
    return "sha256:" + hashlib.sha256(canonical_bytes(unsigned)).hexdigest()


def canonical_subject_digest(value: Any) -> str:
    return "sha256:" + hashlib.sha256(canonical_bytes(value)).hexdigest()


def slug_identifier(value: str) -> str:
    return re.sub(r"[^A-Z0-9]+", "-", value.upper()).strip("-")


def architecture_adr_path(adr_id: str) -> Path:
    matches = sorted(
        (
            ROOT / "docs" / "architecture" / "decisions"
        ).glob(f"{adr_id}-*.md")
    )
    require(
        len(matches) == 1,
        "FIXED_DECISION_GOVERNING_ADR_RESOLUTION",
        f"{adr_id}:{len(matches)}",
    )
    return matches[0]


def accepted_adr_source_catalog() -> tuple[
    list[dict[str, str]],
    dict[str, str],
]:
    """Independently resolve the closed accepted-ADR source authority."""

    source_of_truth_text = SOURCE_OF_TRUTH.read_text(encoding="utf-8")
    owner_rows = re.findall(
        r"^\| Owner decisions \| (.+) \|$",
        source_of_truth_text,
        flags=re.MULTILINE,
    )
    require(
        len(owner_rows) == 1,
        "ACCEPTED_ADR_OWNER_ROW_CARDINALITY",
        str(len(owner_rows)),
    )
    owner_cell = owner_rows[0]
    owner_links = re.findall(
        r"\[(ADR-\d{4})\]\((\./decisions/[^)]+\.md)\)",
        owner_cell,
    )
    require(
        bool(owner_links)
        and owner_cell
        == "; ".join(
            f"[{adr_id}]({relative_path})"
            for adr_id, relative_path in owner_links
        ),
        "ACCEPTED_ADR_OWNER_ROW_SYNTAX",
        "",
    )
    expected_ids: set[str] = set()
    expected_paths: set[str] = set()
    for linked_id, relative_path in owner_links:
        linked_path = (SOURCE_OF_TRUTH.parent / relative_path).resolve()
        try:
            normalized = str(linked_path.relative_to(ROOT.resolve()))
        except ValueError:
            require(
                False,
                "ACCEPTED_ADR_OWNER_LINK_ESCAPE",
                linked_id,
            )
            raise AssertionError("unreachable")
        filename_match = re.fullmatch(
            r"(ADR-\d{4})-[a-z0-9]+(?:-[a-z0-9]+)*\.md",
            linked_path.name,
        )
        require(
            filename_match is not None
            and linked_id == filename_match.group(1),
            "ACCEPTED_ADR_OWNER_LINK_BINDING",
            linked_id,
        )
        require(
            linked_id not in expected_ids
            and normalized not in expected_paths,
            "ACCEPTED_ADR_OWNER_LINK_DUPLICATE",
            linked_id,
        )
        expected_ids.add(linked_id)
        expected_paths.add(normalized)

    decision_root = ROOT / "docs" / "architecture" / "decisions"
    paths = sorted(decision_root.glob("ADR-*.md"))
    rows: list[dict[str, str]] = []
    titles: dict[str, str] = {}
    observed_paths: set[str] = set()
    for path in paths:
        relative_path = str(path.relative_to(ROOT))
        require(
            not path.is_symlink() and path.is_file(),
            "ACCEPTED_ADR_NOT_REGULAR_FILE",
            relative_path,
        )
        filename_match = re.fullmatch(
            r"(ADR-\d{4})-[a-z0-9]+(?:-[a-z0-9]+)*\.md",
            path.name,
        )
        require(
            filename_match is not None,
            "ACCEPTED_ADR_FILENAME",
            relative_path,
        )
        filename_id = filename_match.group(1)
        text = path.read_text(encoding="utf-8")
        heading_matches = re.findall(
            r"^# (ADR-\d{4}): ([^\n]+)$",
            text,
            flags=re.MULTILINE,
        )
        require(
            len(heading_matches) == 1,
            "ACCEPTED_ADR_HEADING_CARDINALITY",
            filename_id,
        )
        heading_id, title = heading_matches[0]

        def exact_header(field: str, pattern: str) -> str:
            matches = re.findall(
                rf"^\| {re.escape(field)} \| `({pattern})` \|$",
                text,
                flags=re.MULTILINE,
            )
            require(
                len(matches) == 1,
                "ACCEPTED_ADR_HEADER_CARDINALITY",
                filename_id + ":" + field,
            )
            return matches[0]

        header_id = exact_header("ADR ID", r"ADR-\d{4}")
        version = exact_header(
            "Version",
            r"(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)",
        )
        status = exact_header("Status", r"[A-Z][A-Z_]*")
        require(
            filename_id == heading_id == header_id,
            "ACCEPTED_ADR_ID_BINDING",
            filename_id,
        )
        require(
            status == "ACCEPTED",
            "ACCEPTED_ADR_STATUS",
            filename_id,
        )
        require(
            filename_id not in titles
            and relative_path not in observed_paths,
            "ACCEPTED_ADR_DUPLICATE",
            filename_id,
        )
        titles[filename_id] = title
        observed_paths.add(relative_path)
        rows.append(
            {
                "adr_id": filename_id,
                "version": version,
                "status": status,
                "source_path": relative_path,
                "source_digest": file_digest(path),
            }
        )

    observed_ids = {row["adr_id"] for row in rows}
    require(
        observed_ids == expected_ids
        and observed_paths == expected_paths
        and len(rows) == len(expected_ids),
        "ACCEPTED_ADR_SOURCE_SET",
        ",".join(sorted(observed_ids ^ expected_ids)),
    )
    return (
        sorted(rows, key=lambda row: row["adr_id"]),
        titles,
    )


def accepted_adr_registry_errors(
    candidate: Any,
    expected_rows: list[dict[str, str]],
) -> set[str]:
    """Return independent fail-closed diagnostics for a registry candidate."""

    errors: set[str] = set()
    expected_registry_keys = {
        "registry_id",
        "version",
        "status",
        "generated_by",
        "entries",
        "required_count",
        "source",
        "source_digest",
    }
    if not isinstance(candidate, dict):
        return {"REGISTRY_SHAPE"}
    if set(candidate) != expected_registry_keys:
        errors.add("REGISTRY_SHAPE")
    expected_metadata = {
        "registry_id": "REG-ACCEPTED-ADRS-001",
        "version": "1.0.0",
        "status": "ACTIVE_DOCUMENTATION_CONTRACT",
        "generated_by": "scripts/architecture/generate_contracts.py",
        "required_count": len(expected_rows),
        "source": str(SOURCE_OF_TRUTH.relative_to(ROOT)),
        "source_digest": file_digest(SOURCE_OF_TRUTH),
    }
    if any(
        candidate.get(key) != value
        for key, value in expected_metadata.items()
    ):
        errors.add("METADATA")
    entries = candidate.get("entries")
    if not isinstance(entries, list):
        errors.add("ENTRY_COLLECTION")
        return errors
    if len(entries) != len(expected_rows):
        errors.add("DENOMINATOR")
    expected_row_keys = {
        "adr_id",
        "version",
        "status",
        "source_path",
        "source_digest",
    }
    ids: list[Any] = []
    paths: list[Any] = []
    for row in entries:
        if not isinstance(row, dict) or set(row) != expected_row_keys:
            errors.add("ROW_SHAPE")
            continue
        ids.append(row["adr_id"])
        paths.append(row["source_path"])
        if row["status"] != "ACCEPTED":
            errors.add("STATUS")
        if re.fullmatch(
            r"(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)",
            row["version"],
        ) is None:
            errors.add("VERSION")
        if re.fullmatch(
            r"docs/architecture/decisions/"
            r"ADR-\d{4}-[a-z0-9]+(?:-[a-z0-9]+)*\.md",
            row["source_path"],
        ) is None:
            errors.add("SOURCE_PATH")
        if re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            row["source_digest"],
        ) is None:
            errors.add("SOURCE_DIGEST")
    if len(ids) != len(set(ids)):
        errors.add("DUPLICATE_ID")
    if len(paths) != len(set(paths)):
        errors.add("DUPLICATE_PATH")
    if entries != expected_rows:
        errors.add("SOURCE_PROJECTION")
    return errors


def validate_accepted_adr_registry(checks: Counter[str]) -> None:
    expected_rows, _ = accepted_adr_source_catalog()
    actual = load_json(CONTRACTS / "accepted-adrs.json")
    errors = accepted_adr_registry_errors(actual, expected_rows)
    require(
        not errors,
        "ACCEPTED_ADR_REGISTRY",
        ",".join(sorted(errors)),
    )
    checks["accepted_adrs"] = len(expected_rows)

    mutations: list[tuple[str, dict[str, Any], str]] = []
    missing = copy.deepcopy(actual)
    missing["entries"].pop()
    mutations.append(("missing-row", missing, "DENOMINATOR"))
    extra = copy.deepcopy(actual)
    extra_row = copy.deepcopy(extra["entries"][-1])
    extra_row.update(
        {
            "adr_id": "ADR-9999",
            "source_path": (
                "docs/architecture/decisions/"
                "ADR-9999-unregistered.md"
            ),
            "source_digest": "sha256:" + "9" * 64,
        }
    )
    extra["entries"].append(extra_row)
    mutations.append(("extra-row", extra, "DENOMINATOR"))
    duplicate = copy.deepcopy(actual)
    duplicate["entries"][-1] = copy.deepcopy(duplicate["entries"][0])
    mutations.append(("duplicate-id-path", duplicate, "DUPLICATE_ID"))
    wrong_status = copy.deepcopy(actual)
    wrong_status["entries"][0]["status"] = "PROPOSED"
    mutations.append(("wrong-status", wrong_status, "STATUS"))
    wrong_version = copy.deepcopy(actual)
    wrong_version["entries"][0]["version"] = "1.0"
    mutations.append(("wrong-version", wrong_version, "VERSION"))
    wrong_path = copy.deepcopy(actual)
    wrong_path["entries"][0]["source_path"] = (
        "docs/architecture/decisions/ADR-0001-wrong.md"
    )
    mutations.append(("wrong-path", wrong_path, "SOURCE_PROJECTION"))
    wrong_digest = copy.deepcopy(actual)
    wrong_digest["entries"][0]["source_digest"] = (
        "sha256:" + "0" * 64
    )
    mutations.append(
        ("wrong-source-digest", wrong_digest, "SOURCE_PROJECTION")
    )
    wrong_authority_digest = copy.deepcopy(actual)
    wrong_authority_digest["source_digest"] = "sha256:" + "0" * 64
    mutations.append(
        ("wrong-authority-digest", wrong_authority_digest, "METADATA")
    )
    for case_id, candidate, required_error in mutations:
        mutation_errors = accepted_adr_registry_errors(
            candidate,
            expected_rows,
        )
        require(
            required_error in mutation_errors,
            "ACCEPTED_ADR_NEGATIVE_CASE_ACCEPTED",
            case_id,
        )
        checks["accepted_adr_negative_cases"] += 1


def fixed_decision_fitness_definitions() -> dict[str, dict[str, str]]:
    definitions: dict[str, dict[str, str]] = {}
    for adr_id in (
        "ADR-0003",
        "ADR-0004",
        "ADR-0005",
        "ADR-0006",
        "ADR-0011",
    ):
        path = architecture_adr_path(adr_id)
        for fitness_id, required_result in re.findall(
            r"^\| `(FF-[A-Z0-9-]+)` \| ([^|\n]+) \|$",
            path.read_text(encoding="utf-8"),
            flags=re.MULTILINE,
        ):
            require(
                fitness_id not in definitions,
                "FIXED_DECISION_FITNESS_DEFINITION_DUPLICATE",
                fitness_id,
            )
            definitions[fitness_id] = {
                "fitness_id": fitness_id,
                "required_result": required_result.strip(),
                "source": str(path.relative_to(ROOT)),
            }
    require(
        bool(definitions),
        "FIXED_DECISION_FITNESS_DEFINITIONS_MISSING",
        "",
    )
    return definitions


def validate_unique_architecture_fitness_definitions(
    checks: Counter[str],
) -> None:
    definitions: dict[str, str] = {}
    for path in sorted(
        (
            ROOT / "docs" / "architecture" / "decisions"
        ).glob("ADR-*.md")
    ):
        for fitness_id in re.findall(
            r"^\| `(FF-[A-Z0-9-]+)` \| [^|\n]+ \|$",
            path.read_text(encoding="utf-8"),
            flags=re.MULTILINE,
        ):
            require(
                fitness_id not in definitions,
                "ARCHITECTURE_FITNESS_DEFINITION_DUPLICATE",
                (
                    f"{fitness_id}:{definitions.get(fitness_id, '')}:"
                    f"{path.relative_to(ROOT)}"
                ),
            )
            definitions[fitness_id] = str(path.relative_to(ROOT))
    require(
        bool(definitions),
        "ARCHITECTURE_FITNESS_DEFINITION_SET_EMPTY",
        "",
    )
    checks["architecture_fitness_definitions"] += len(definitions)


def expected_fixed_decisions_from_source() -> list[dict[str, Any]]:
    text = FIXED_DECISION_ADR.read_text(encoding="utf-8")
    candidates: list[dict[str, Any]] = []
    for block in re.findall(
        r"```yaml\s*\n(.*?)\n```",
        text,
        flags=re.DOTALL,
    ):
        parsed = yaml.load(block, Loader=DuplicateKeyLoader)
        if (
            isinstance(parsed, dict)
            and parsed.get("register_id") == "RANEX-FIXED-DECISIONS"
        ):
            candidates.append(parsed)
    require(
        len(candidates) == 1,
        "FIXED_DECISION_REGISTER_BLOCK_COUNT",
        str(len(candidates)),
    )
    register = candidates[0]
    require(
        set(register)
        == {
            "schema_version",
            "register_id",
            "required_count",
            "decisions",
        },
        "FIXED_DECISION_REGISTER_FIELDS",
        "",
    )
    decisions = register["decisions"]
    require(
        register["schema_version"] == "1.0.0"
        and register["required_count"] == 29
        and isinstance(decisions, list)
        and len(decisions) == 29,
        "FIXED_DECISION_DENOMINATOR",
        str(len(decisions) if isinstance(decisions, list) else -1),
    )
    expected_ids = [
        f"DEC-RANEX-{index:03d}" for index in range(1, 30)
    ]
    actual_ids = [
        row.get("decision_id") if isinstance(row, dict) else None
        for row in decisions
    ]
    require(
        actual_ids == expected_ids
        and len(actual_ids) == len(set(actual_ids)),
        "FIXED_DECISION_ID_RANGE_ORDER_UNIQUENESS",
        ",".join(str(item) for item in actual_ids),
    )
    row_fields = {
        "decision_id",
        "name",
        "selected",
        "owner",
        "governing_adr",
        "alternatives",
        "fitness_functions",
        "status",
    }
    fitness_definitions = fixed_decision_fitness_definitions()
    source_digest = file_digest(FIXED_DECISION_ADR)
    expected: list[dict[str, Any]] = []
    for row in decisions:
        decision_id = row["decision_id"]
        require(
            set(row) == row_fields,
            "FIXED_DECISION_ROW_FIELDS",
            decision_id,
        )
        require(
            all(
                isinstance(row[field], str) and bool(row[field].strip())
                for field in (
                    "decision_id",
                    "name",
                    "selected",
                    "owner",
                    "governing_adr",
                    "status",
                )
            ),
            "FIXED_DECISION_BLANK_SCALAR",
            decision_id,
        )
        for field in ("alternatives", "fitness_functions"):
            values = row[field]
            require(
                isinstance(values, list)
                and bool(values)
                and all(
                    isinstance(value, str) and bool(value.strip())
                    for value in values
                )
                and len(values) == len(set(values)),
                "FIXED_DECISION_LIST_INVALID",
                f"{decision_id}:{field}",
            )
        require(
            row["selected"] not in row["alternatives"],
            "FIXED_DECISION_SELECTED_REPEATED",
            decision_id,
        )
        require(
            row["status"] == "ACCEPTED",
            "FIXED_DECISION_STATUS",
            decision_id,
        )
        governing_path = architecture_adr_path(row["governing_adr"])
        status_match = re.search(
            r"^\| Status \| `?([A-Z_]+)`? \|$",
            governing_path.read_text(encoding="utf-8"),
            flags=re.MULTILINE,
        )
        require(
            status_match is not None
            and status_match.group(1) == "ACCEPTED",
            "FIXED_DECISION_GOVERNING_ADR_STATUS",
            decision_id,
        )
        unknown_fitness = (
            set(row["fitness_functions"]) - set(fitness_definitions)
        )
        require(
            not unknown_fitness,
            "FIXED_DECISION_FITNESS_CLOSURE",
            f"{decision_id}:{','.join(sorted(unknown_fitness))}",
        )
        expected.append(
            {
                **copy.deepcopy(row),
                "source": str(FIXED_DECISION_ADR.relative_to(ROOT)),
                "source_digest": source_digest,
                "governing_adr_source": str(
                    governing_path.relative_to(ROOT)
                ),
                "governing_adr_digest": file_digest(governing_path),
            }
        )
    return expected


