def estimate_commitment_source_row(
    role: str,
    work_item_id: str,
) -> dict[str, Any]:
    schema_ref = (
        "work-item-scope/v1"
        if role == "SCOPE"
        else role.lower().replace("_", "-") + "-source/v1"
    )
    row = {
        "role": role,
        "schema_ref": schema_ref,
        "ref": (
            "urn:ranex:"
            + role.lower().replace("_", "-")
            + ":"
            + work_item_id
        ),
        "work_item_id": work_item_id,
        "valid_from": "2026-01-01T00:00:00Z",
        "valid_until": "2027-01-01T00:00:00Z",
        "current": True,
    }
    row["digest"] = canonical_subject_digest(
        {
            key: value
            for key, value in row.items()
            if key != "current"
        }
    )
    return row


def estimate_method_authority_row(
    work_item_id: str,
) -> dict[str, Any]:
    payload = {
        "method_schema": "estimate-method/v1",
        "method_version": "1.0.0",
        "method_id": "three-point",
        "work_item_id": work_item_id,
        "valid_from": "2026-01-01T00:00:00Z",
        "valid_until": "2027-01-01T00:00:00Z",
        "independently_governed": True,
    }
    payload_digest = canonical_subject_digest(payload)
    return {
        "method_ref": (
            "urn:ranex:estimate-method:three-point:"
            + payload_digest.removeprefix("sha256:")
        ),
        **payload,
        "digest": payload_digest,
        "current": True,
    }


def estimate_evidence_authority_row(
    work_item_id: str,
) -> dict[str, Any]:
    row = {
        "evidence_ref": "urn:ranex:evidence:estimate-basis",
        "evidence_schema": "estimate-evidence/v1",
        "evidence_version": "1.0.0",
        "evidence_id": "estimate-basis",
        "work_item_id": work_item_id,
        "captured_at": "2026-07-26T00:00:00Z",
        "valid_until": "2027-01-01T00:00:00Z",
        "content": {
            "source": "planning-workshop",
            "basis": "three-point-observation",
        },
        "current": True,
    }
    row["digest"] = canonical_subject_digest(
        {
            key: value
            for key, value in row.items()
            if key != "current"
        }
    )
    return row


def estimate_commitment_subject(
    world: dict[str, Any],
) -> dict[str, Any]:
    sources = world["sources"]
    work_item_id = world["work_item_id"]
    estimates = sources["ESTIMATE"]["observations"]
    estimate_bindings = sorted(
        [
            {
                "estimate_id": row["estimate_id"],
                "estimate_digest": row["digest"],
                "estimate_kind": row["estimate_kind"],
                "unit": row["unit"],
            }
            for row in estimates
            if row["estimate_id"] in world["bound_estimate_ids"]
        ],
        key=lambda row: row["estimate_id"].encode("utf-8"),
    )
    plan = sources["PLAN"]
    scope = sources["SCOPE"]
    capacity = sources["CAPACITY"]
    dependency = sources["DEPENDENCY"]
    risk = sources["RISK"]
    acceptance = sources["ACCEPTANCE"]
    plan_digest_component = plan["digest"].removeprefix("sha256:")
    values = {
        "subject_schema": "delivery-commitment-subject/v1",
        "subject_ref": (
            "urn:ranex:delivery-commitment:"
            + work_item_id
            + ":"
            + plan_digest_component
        ),
        "work_item_id": work_item_id,
        "plan_ref": plan["ref"],
        "plan_digest": plan["digest"],
        "scope_ref": scope["ref"],
        "scope_digest": scope["digest"],
        "estimate_bindings": estimate_bindings,
        "capacity_snapshot_ref": capacity["ref"],
        "capacity_snapshot_digest": capacity["digest"],
        "dependency_snapshot_ref": dependency["ref"],
        "dependency_snapshot_digest": dependency["digest"],
        "risk_snapshot_ref": risk["ref"],
        "risk_snapshot_digest": risk["digest"],
        "acceptance_snapshot_ref": acceptance["ref"],
        "acceptance_snapshot_digest": acceptance["digest"],
        "commitment_owner_id": sources["OWNER"]["principal_id"],
        "commitment_window_start": "2026-07-28T00:00:00Z",
        "commitment_window_end": "2026-08-15T00:00:00Z",
        "recommit_trigger_ids": copy.deepcopy(
            ESTIMATE_COMMITMENT_TRIGGERS
        ),
    }
    projection = estimate_commitment_machine_contract()[
        "commitment_subject_projection"
    ]
    require(
        list(values) == projection["output_fields"],
        "ESTIMATE_COMMITMENT_PROJECTION_ORDER",
        "",
    )
    return values


def estimate_commitment_decision(
    subject: dict[str, Any],
    *,
    decision_id: str = "dec_estimate_commitment_current",
    supersedes: str | None = None,
) -> dict[str, Any]:
    subject_digest = canonical_subject_digest(subject)
    decision = {
        "schema_version": "1",
        "artifact_type": "human_decision",
        "decision_id": decision_id,
        "principal_id": subject["commitment_owner_id"],
        "authentication_context_id": "auth_" + decision_id,
        "presentation_challenge_digest": canonical_subject_digest(
            {"decision_id": decision_id, "kind": "challenge"}
        ),
        "status": "APPROVED",
        "decision_kind": "WORK_TRANSITION",
        "outcome": "APPROVED",
        "core_sdlc_trace_ref": (
            "trace_" + subject["work_item_id"]
        ),
        "subject": {
            "subject_schema": subject["subject_schema"],
            "subject_ref": subject["subject_ref"],
            "subject_digest": subject_digest,
            "subject_manifest_digest": None,
        },
        "action": {
            "action_type": "COMMIT_DELIVERY_SCOPE",
            "canonical_argument_digest": subject_digest,
            "destination": subject["work_item_id"],
            "adapter_id": "policy",
            "adapter_version": "1.0.0",
        },
        "reason": "Accountable delivery commitment for the exact plan.",
        "scope": sorted(
            [
                subject["work_item_id"],
                subject["plan_ref"],
                subject["scope_ref"],
            ],
            key=lambda value: value.encode("utf-8"),
        ),
        "conditions": copy.deepcopy(
            subject["recommit_trigger_ids"]
        ),
        "nonce": "nonce_" + decision_id,
        "issued_at": "2026-07-28T01:00:00Z",
        "expires_at": subject["commitment_window_end"],
        "revoked_at": None,
        "supersedes": supersedes,
        "evidence_refs": [],
        "digest": "",
    }
    decision["digest"] = digest(decision)
    return decision


def estimate_commitment_decision_source(
    decisions: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "records": decisions,
        "authentication_contexts": [
            {
                "authentication_context_id": decision[
                    "authentication_context_id"
                ],
                "principal_id": decision["principal_id"],
                "current": True,
            }
            for decision in decisions
        ],
        "presentation_challenges": [
            {
                "presentation_challenge_digest": decision[
                    "presentation_challenge_digest"
                ],
                "principal_id": decision["principal_id"],
                "current": True,
            }
            for decision in decisions
        ],
        "nonces": [
            {
                "nonce": decision["nonce"],
                "principal_id": decision["principal_id"],
                "current": True,
                "use_count": 1,
            }
            for decision in decisions
        ],
        "artifact_registry": [
            {
                "artifact_ref": decision["decision_id"],
                "artifact_type": "human_decision",
                "artifact_digest": decision["digest"],
                "current": True,
            }
            for decision in decisions
        ],
    }


def build_estimate_commitment_world() -> dict[str, Any]:
    work_item_id = "work_estimate_commitment"
    method = estimate_method_authority_row(work_item_id)
    evidence = estimate_evidence_authority_row(work_item_id)
    estimate = {
        "schema_version": "1",
        "record_type": "ESTIMATE_OBSERVATION",
        "estimate_id": "estimate_current",
        "work_item_id": work_item_id,
        "subject_schema": "work-scope/v1",
        "subject_ref": "urn:ranex:work-scope:" + work_item_id,
        "subject_digest": "sha256:" + "1" * 64,
        "estimate_kind": "EFFORT",
        "unit": "person-day",
        "lower_bound": 2,
        "most_likely": 3,
        "upper_bound": 5,
        "confidence": "MEDIUM",
        "method_ref": method["method_ref"],
        "assumptions": ["stable-scope"],
        "evidence_bindings": [
            {
                "evidence_ref": evidence["evidence_ref"],
                "evidence_digest": evidence["digest"],
            }
        ],
        "capacity_snapshot_ref": (
            "urn:ranex:capacity:" + work_item_id
        ),
        "capacity_snapshot_digest": "sha256:" + "3" * 64,
        "dependency_snapshot_ref": (
            "urn:ranex:dependency:" + work_item_id
        ),
        "dependency_snapshot_digest": "sha256:" + "4" * 64,
        "prepared_by_principal_id": "principal_delivery_owner",
        "observed_at": "2026-07-27T00:00:00Z",
        "valid_until": "2026-08-31T00:00:00Z",
        "supersedes_estimate_id": None,
        "digest": "",
    }
    estimate["digest"] = digest(estimate)
    sources: dict[str, Any] = {
        "ESTIMATE": {
            "observations": [estimate],
            "methods": [method],
            "evidence": [evidence],
        },
        "PLAN": estimate_commitment_source_row(
            "PLAN",
            work_item_id,
        ),
        "SCOPE": estimate_commitment_source_row(
            "SCOPE",
            work_item_id,
        ),
        "CAPACITY": estimate_commitment_source_row(
            "CAPACITY",
            work_item_id,
        ),
        "DEPENDENCY": estimate_commitment_source_row(
            "DEPENDENCY",
            work_item_id,
        ),
        "RISK": estimate_commitment_source_row(
            "RISK",
            work_item_id,
        ),
        "ACCEPTANCE": estimate_commitment_source_row(
            "ACCEPTANCE",
            work_item_id,
        ),
        "OWNER": {
            "principal_id": "principal_delivery_owner",
            "work_item_id": work_item_id,
            "role": "ACCOUNTABLE_DELIVERY_OWNER",
            "authenticated": True,
            "current": True,
        },
        "DECISION": estimate_commitment_decision_source([]),
        "TRACE": {
            "trace_ref": "trace_" + work_item_id,
            "work_item_id": work_item_id,
            "current": True,
        },
        "TIME": {
            "observed_at": "2026-07-29T00:00:00Z",
            "trusted": True,
        },
    }
    estimate["capacity_snapshot_ref"] = sources["CAPACITY"]["ref"]
    estimate["capacity_snapshot_digest"] = sources["CAPACITY"]["digest"]
    estimate["dependency_snapshot_ref"] = sources["DEPENDENCY"]["ref"]
    estimate["dependency_snapshot_digest"] = sources["DEPENDENCY"][
        "digest"
    ]
    estimate["subject_schema"] = sources["SCOPE"]["schema_ref"]
    estimate["subject_ref"] = sources["SCOPE"]["ref"]
    estimate["subject_digest"] = sources["SCOPE"]["digest"]
    estimate["digest"] = digest(estimate)
    world = {
        "work_item_id": work_item_id,
        "bound_estimate_ids": [estimate["estimate_id"]],
        "sources": sources,
        "presented_subject": {},
        "query_kind": "COMMITMENT",
        "fired_recommit_triggers": [],
        "requested_authority": "DELIVERY_COMMITMENT_ONLY",
        "prior_subjects": [],
        "caller_receipts": [],
    }
    world["presented_subject"] = estimate_commitment_subject(world)
    sources["DECISION"] = estimate_commitment_decision_source(
        [estimate_commitment_decision(world["presented_subject"])]
    )
    return world


def validate_estimate_supersession(
    estimates: list[dict[str, Any]],
) -> dict[str, str]:
    by_id = {
        row["estimate_id"]: row for row in estimates
    }
    require(
        len(by_id) == len(estimates),
        "ESTIMATE_ID_DUPLICATE",
        "",
    )
    successor_by_id: dict[str, str] = {}
    supersession_pairs: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for row in estimates:
        predecessor = row["supersedes_estimate_id"]
        if predecessor is None:
            continue
        require(
            predecessor in by_id and predecessor != row["estimate_id"],
            "ESTIMATE_SUPERSESSION_REFERENCE",
            row["estimate_id"],
        )
        require(
            predecessor not in successor_by_id,
            "ESTIMATE_SUPERSESSION_DUPLICATE",
            predecessor,
        )
        successor_by_id[predecessor] = row["estimate_id"]
        supersession_pairs.append((by_id[predecessor], row))
    for estimate_id in by_id:
        seen: set[str] = set()
        current = estimate_id
        while current in successor_by_id:
            require(
                current not in seen,
                "ESTIMATE_SUPERSESSION_CYCLE",
                estimate_id,
            )
            seen.add(current)
            current = successor_by_id[current]
    for predecessor, successor in supersession_pairs:
        require(
            successor["work_item_id"] == predecessor["work_item_id"]
            and parse_utc_datetime(
                predecessor["observed_at"],
                "ESTIMATE_SUPERSESSION_CHRONOLOGY",
                predecessor["estimate_id"],
            )
            < parse_utc_datetime(
                successor["observed_at"],
                "ESTIMATE_SUPERSESSION_CHRONOLOGY",
                successor["estimate_id"],
            ),
            "ESTIMATE_SUPERSESSION_CHRONOLOGY",
            successor["estimate_id"],
        )
    return successor_by_id


def resolve_estimate_commitment(
    world: dict[str, Any],
    schemas: dict[str, dict[str, Any]],
    *,
    caller_id: str,
) -> dict[str, Any]:
    contract = estimate_commitment_machine_contract()
    expected_roles = [
        row["role"]
        for row in contract["resolver_contract"]["required_sources"]
    ]
    sources = world["sources"]
    require(
        list(sources) == expected_roles
        and set(sources) == set(expected_roles),
        "ESTIMATE_COMMITMENT_SOURCE_SET",
        "",
    )
    require(
        sources["TIME"]["trusted"] is True,
        "ESTIMATE_COMMITMENT_TRUSTED_TIME",
        "",
    )
    observed_at = parse_utc_datetime(
        sources["TIME"]["observed_at"],
        "ESTIMATE_COMMITMENT_TIME",
        "",
    )
    require(
        world["query_kind"] in {"ESTIMATE_ONLY", "COMMITMENT"},
        "ESTIMATE_COMMITMENT_QUERY_KIND",
        str(world["query_kind"]),
    )
    estimate_schema = schemas[
        contract["estimate_record"]["schema_ref"]
    ]
    estimate_source = sources["ESTIMATE"]
    require(
        isinstance(estimate_source, dict)
        and list(estimate_source)
        == ["observations", "methods", "evidence"]
        and all(
            isinstance(estimate_source[key], list)
            for key in estimate_source
        ),
        "ESTIMATE_SOURCE_REGISTRY_SHAPE",
        "",
    )
    estimates = estimate_source["observations"]
    method_rows = estimate_source["methods"]
    evidence_rows = estimate_source["evidence"]
    resolved_method_refs: set[str] = set()
    resolved_evidence_bindings: set[tuple[str, str]] = set()
    for estimate in estimates:
        errors = list(
            jsonschema.Draft202012Validator(
                estimate_schema,
                format_checker=jsonschema.FormatChecker(),
            ).iter_errors(estimate)
        )
        require(
            not errors,
            "ESTIMATE_OBSERVATION_SCHEMA",
            errors[0].message if errors else "",
        )
        require(
            estimate["digest"] == digest(estimate),
            "ESTIMATE_OBSERVATION_DIGEST",
            estimate["estimate_id"],
        )
        require(
            estimate["lower_bound"] <= estimate["upper_bound"]
            and (
                estimate["most_likely"] is None
                or estimate["lower_bound"]
                <= estimate["most_likely"]
                <= estimate["upper_bound"]
            ),
            "ESTIMATE_OBSERVATION_RANGE",
            estimate["estimate_id"],
        )
        require(
            parse_utc_datetime(
                estimate["observed_at"],
                "ESTIMATE_OBSERVATION_TIME",
                estimate["estimate_id"],
            )
            < parse_utc_datetime(
                estimate["valid_until"],
                "ESTIMATE_OBSERVATION_TIME",
                estimate["estimate_id"],
            ),
            "ESTIMATE_OBSERVATION_TIME",
            estimate["estimate_id"],
        )
        estimate_observed_at = parse_utc_datetime(
            estimate["observed_at"],
            "ESTIMATE_OBSERVATION_FUTURE",
            estimate["estimate_id"],
        )
        require(
            estimate_observed_at <= observed_at,
            "ESTIMATE_OBSERVATION_FUTURE",
            estimate["estimate_id"],
        )
        scope = sources["SCOPE"]
        require(
            set(scope)
            == {
                "role",
                "schema_ref",
                "ref",
                "work_item_id",
                "valid_from",
                "valid_until",
                "current",
                "digest",
            }
            and scope["role"] == "SCOPE"
            and estimate["subject_schema"] == scope["schema_ref"],
            "ESTIMATE_SUBJECT_SCHEMA",
            estimate["estimate_id"],
        )
        require(
            estimate["subject_ref"] == scope["ref"],
            "ESTIMATE_SUBJECT_REF",
            estimate["estimate_id"],
        )
        require(
            estimate["subject_digest"] == scope["digest"]
            and scope["digest"]
            == canonical_subject_digest(
                {
                    key: value
                    for key, value in scope.items()
                    if key not in {"digest", "current"}
                }
            ),
            "ESTIMATE_SUBJECT_DIGEST",
            estimate["estimate_id"],
        )
        require(
            scope["work_item_id"] == estimate["work_item_id"],
            "ESTIMATE_SUBJECT_WORK_ITEM",
            estimate["estimate_id"],
        )
        require(
            scope["current"] is True
            and parse_utc_datetime(
                scope["valid_from"],
                "ESTIMATE_SUBJECT_CURRENTNESS",
                estimate["estimate_id"],
            )
            <= estimate_observed_at
            < parse_utc_datetime(
                scope["valid_until"],
                "ESTIMATE_SUBJECT_CURRENTNESS",
                estimate["estimate_id"],
            ),
            "ESTIMATE_SUBJECT_CURRENTNESS",
            estimate["estimate_id"],
        )
        method_matches = [
            row
            for row in method_rows
            if row.get("method_ref") == estimate["method_ref"]
        ]
        require(
            len(method_matches) == 1,
            "ESTIMATE_METHOD_UNRESOLVED",
            estimate["method_ref"],
        )
        method = method_matches[0]
        require(
            set(method)
            == {
                "method_ref",
                "method_schema",
                "method_version",
                "method_id",
                "work_item_id",
                "valid_from",
                "valid_until",
                "independently_governed",
                "digest",
                "current",
            },
            "ESTIMATE_METHOD_SCHEMA",
            estimate["method_ref"],
        )
        require(
            method["method_schema"] == "estimate-method/v1",
            "ESTIMATE_METHOD_SCHEMA",
            estimate["method_ref"],
        )
        require(
            method["method_version"] == "1.0.0",
            "ESTIMATE_METHOD_VERSION",
            estimate["method_ref"],
        )
        require(
            method["work_item_id"] == estimate["work_item_id"],
            "ESTIMATE_METHOD_WORK_ITEM",
            estimate["method_ref"],
        )
        require(
            method["independently_governed"] is True,
            "ESTIMATE_METHOD_INDEPENDENCE",
            estimate["method_ref"],
        )
        method_payload = {
            key: value
            for key, value in method.items()
            if key not in {"method_ref", "digest", "current"}
        }
        recomputed_method_digest = canonical_subject_digest(
            method_payload
        )
        require(
            method["digest"] == recomputed_method_digest
            and method["method_ref"]
            == (
                "urn:ranex:estimate-method:"
                + method["method_id"]
                + ":"
                + recomputed_method_digest.removeprefix("sha256:")
            ),
            "ESTIMATE_METHOD_DIGEST",
            estimate["method_ref"],
        )
        require(
            method["current"] is True
            and parse_utc_datetime(
                method["valid_from"],
                "ESTIMATE_METHOD_CURRENTNESS",
                estimate["method_ref"],
            )
            <= estimate_observed_at
            < parse_utc_datetime(
                method["valid_until"],
                "ESTIMATE_METHOD_CURRENTNESS",
                estimate["method_ref"],
            ),
            "ESTIMATE_METHOD_CURRENTNESS",
            estimate["method_ref"],
        )
        resolved_method_refs.add(method["method_ref"])
        evidence_bindings = estimate["evidence_bindings"]
        evidence_keys = [
            (
                binding["evidence_ref"],
                binding["evidence_digest"],
            )
            for binding in evidence_bindings
        ]
        require(
            evidence_keys
            == sorted(
                evidence_keys,
                key=lambda value: (
                    value[0].encode("utf-8"),
                    value[1].encode("utf-8"),
                ),
            )
            and len(evidence_keys) == len(set(evidence_keys)),
            "ESTIMATE_EVIDENCE_BINDING_SET",
            estimate["estimate_id"],
        )
        for evidence_binding in evidence_bindings:
            evidence_matches = [
                row
                for row in evidence_rows
                if row.get("evidence_ref")
                == evidence_binding["evidence_ref"]
            ]
            require(
                len(evidence_matches) == 1,
                "ESTIMATE_EVIDENCE_UNRESOLVED",
                evidence_binding["evidence_ref"],
            )
            evidence = evidence_matches[0]
            require(
                set(evidence)
                == {
                    "evidence_ref",
                    "evidence_schema",
                    "evidence_version",
                    "evidence_id",
                    "work_item_id",
                    "captured_at",
                    "valid_until",
                    "content",
                    "current",
                    "digest",
                }
                and evidence["evidence_schema"]
                == "estimate-evidence/v1",
                "ESTIMATE_EVIDENCE_SCHEMA",
                evidence_binding["evidence_ref"],
            )
            require(
                evidence["evidence_version"] == "1.0.0",
                "ESTIMATE_EVIDENCE_VERSION",
                evidence_binding["evidence_ref"],
            )
            require(
                evidence["work_item_id"] == estimate["work_item_id"],
                "ESTIMATE_EVIDENCE_WORK_ITEM",
                evidence_binding["evidence_ref"],
            )
            require(
                evidence["current"] is True
                and parse_utc_datetime(
                    evidence["captured_at"],
                    "ESTIMATE_EVIDENCE_CURRENTNESS",
                    evidence_binding["evidence_ref"],
                )
                <= estimate_observed_at
                < parse_utc_datetime(
                    evidence["valid_until"],
                    "ESTIMATE_EVIDENCE_CURRENTNESS",
                    evidence_binding["evidence_ref"],
                ),
                "ESTIMATE_EVIDENCE_CURRENTNESS",
                evidence_binding["evidence_ref"],
            )
            recomputed_evidence_digest = canonical_subject_digest(
                {
                    key: value
                    for key, value in evidence.items()
                    if key not in {"digest", "current"}
                }
            )
            require(
                evidence_binding["evidence_digest"]
                == evidence["digest"]
                == recomputed_evidence_digest,
                "ESTIMATE_EVIDENCE_DIGEST",
                evidence_binding["evidence_ref"],
            )
            resolved_evidence_bindings.add(
                (
                    evidence["evidence_ref"],
                    evidence["digest"],
                )
            )
    require(
        resolved_method_refs
        == {
            row.get("method_ref")
            for row in method_rows
        },
        "ESTIMATE_METHOD_REGISTRY_CLOSURE",
        "",
    )
    require(
        resolved_evidence_bindings
        == {
            (row.get("evidence_ref"), row.get("digest"))
            for row in evidence_rows
        },
        "ESTIMATE_EVIDENCE_REGISTRY_CLOSURE",
        "",
    )
    successors = validate_estimate_supersession(estimates)
    estimates_by_id = {
        row["estimate_id"]: row for row in estimates
    }
    require(
        world["bound_estimate_ids"]
        == sorted(
            world["bound_estimate_ids"],
            key=lambda value: value.encode("utf-8"),
        )
        and len(world["bound_estimate_ids"])
        == len(set(world["bound_estimate_ids"]))
        and world["bound_estimate_ids"],
        "DELIVERY_COMMITMENT_ESTIMATE_BINDING_SET",
        "",
    )
    for estimate_id in world["bound_estimate_ids"]:
        require(
            estimate_id in estimates_by_id,
            "DELIVERY_COMMITMENT_ESTIMATE_BINDING",
            estimate_id,
        )
        estimate = estimates_by_id[estimate_id]
        require(
            estimate["work_item_id"] == world["work_item_id"],
            "DELIVERY_COMMITMENT_WORK_ITEM",
            estimate_id,
        )
        require(
            estimate["subject_ref"] == sources["SCOPE"]["ref"]
            and estimate["subject_digest"]
            == sources["SCOPE"]["digest"],
            "ESTIMATE_SCOPE_BINDING",
            estimate_id,
        )
        require(
            estimate["capacity_snapshot_ref"]
            == sources["CAPACITY"]["ref"]
            and estimate["capacity_snapshot_digest"]
            == sources["CAPACITY"]["digest"],
            "ESTIMATE_CAPACITY_BINDING",
            estimate_id,
        )
        require(
            estimate["dependency_snapshot_ref"]
            == sources["DEPENDENCY"]["ref"]
            and estimate["dependency_snapshot_digest"]
            == sources["DEPENDENCY"]["digest"],
            "ESTIMATE_DEPENDENCY_BINDING",
            estimate_id,
        )
        require(
            estimate_id not in successors,
            "DELIVERY_COMMITMENT_ESTIMATE_CURRENTNESS",
            estimate_id,
        )
        require(
            observed_at
            < parse_utc_datetime(
                estimate["valid_until"],
                "DELIVERY_COMMITMENT_ESTIMATE_EXPIRED",
                estimate_id,
            ),
            "DELIVERY_COMMITMENT_ESTIMATE_EXPIRED",
            estimate_id,
        )
    if world["query_kind"] == "ESTIMATE_ONLY":
        require(
            sources["DECISION"]["records"] == [],
            "ESTIMATE_ONLY_DECISION_PRESENT",
            "",
        )
        receipt = {
            "caller_id": caller_id,
            "result": "ESTIMATE_ONLY_NON_AUTHORITATIVE",
            "authority_granted": False,
            "resolved_source_roles": copy.deepcopy(expected_roles),
        }
        world["caller_receipts"].append(receipt)
        return receipt
    decision_source = sources["DECISION"]
    require(
        set(decision_source)
        == {
            "records",
            "authentication_contexts",
            "presentation_challenges",
            "nonces",
            "artifact_registry",
        },
        "DELIVERY_COMMITMENT_DECISION_SOURCE",
        "",
    )
    decisions = decision_source["records"]
    if decisions and decisions[0].get("record_type") == (
        "ESTIMATE_OBSERVATION"
    ):
        raise ContractFailure(
            "ESTIMATE_CANNOT_GRANT_COMMITMENT:"
        )
    require(
        decisions,
        "DELIVERY_COMMITMENT_DECISION_MISSING",
        "",
    )
    independently_derived = estimate_commitment_subject(world)
    presented = world["presented_subject"]
    window_start = parse_utc_datetime(
        presented["commitment_window_start"],
        "DELIVERY_COMMITMENT_WINDOW",
        "",
    )
    window_end = parse_utc_datetime(
        presented["commitment_window_end"],
        "DELIVERY_COMMITMENT_WINDOW",
        "",
    )
    require(
        window_start < window_end,
        "DELIVERY_COMMITMENT_WINDOW",
        "",
    )
    require(
        presented["recommit_trigger_ids"]
        == ESTIMATE_COMMITMENT_TRIGGERS,
        "DELIVERY_COMMITMENT_TRIGGER_SET",
        "",
    )
    subject_schema = schemas[
        contract["commitment_subject_projection"]["schema_ref"]
    ]
    subject_errors = list(
        jsonschema.Draft202012Validator(
            subject_schema,
            format_checker=jsonschema.FormatChecker(),
        ).iter_errors(presented)
    )
    require(
        not subject_errors,
        "DELIVERY_COMMITMENT_SUBJECT_SCHEMA",
        subject_errors[0].message if subject_errors else "",
    )
    require(
        presented == independently_derived,
        "DELIVERY_COMMITMENT_BOUND_SOURCE_DRIFT",
        "",
    )
    for role in (
        "PLAN",
        "SCOPE",
        "CAPACITY",
        "DEPENDENCY",
        "RISK",
        "ACCEPTANCE",
    ):
        row = sources[role]
        require(
            row["work_item_id"] == world["work_item_id"],
            "DELIVERY_COMMITMENT_WORK_ITEM",
            role,
        )
        require(
            row["current"] is True,
            "DELIVERY_COMMITMENT_" + role + "_BINDING",
            "",
        )
        require(
            row["digest"]
            == canonical_subject_digest(
                {
                    key: value
                    for key, value in row.items()
                    if key not in {"digest", "current"}
                }
            ),
            "DELIVERY_COMMITMENT_" + role + "_BINDING",
            "digest",
        )
    expected_subject_digest = canonical_subject_digest(presented)
    same_ref = [
        decision
        for decision in decisions
        if decision.get("subject", {}).get("subject_ref")
        == presented["subject_ref"]
    ]
    require(
        same_ref,
        "DELIVERY_COMMITMENT_SUBJECT_REF",
        "",
    )
    exact_matching = [
        decision
        for decision in same_ref
        if decision["subject"]["subject_digest"]
        == expected_subject_digest
    ]
    require(
        exact_matching,
        "DELIVERY_COMMITMENT_SUBJECT_DIGEST",
        "",
    )
    require(
        len(exact_matching) == 1,
        "DELIVERY_COMMITMENT_DECISION_CARDINALITY",
        str(len(exact_matching)),
    )
    decision = exact_matching[0]
    require(
        decision["status"] == "APPROVED",
        "DELIVERY_COMMITMENT_DECISION_STATUS",
        "",
    )
    require(
        decision["decision_kind"] == "WORK_TRANSITION",
        "DELIVERY_COMMITMENT_DECISION_KIND",
        "",
    )
    require(
        decision["outcome"] == "APPROVED",
        "DELIVERY_COMMITMENT_DECISION_OUTCOME",
        "",
    )
    require(
        decision["action"]["action_type"]
        == "COMMIT_DELIVERY_SCOPE",
        "DELIVERY_COMMITMENT_DECISION_ACTION",
        "",
    )
    require(
        decision["action"]["canonical_argument_digest"]
        == expected_subject_digest,
        "DELIVERY_COMMITMENT_ARGUMENT_DIGEST",
        "",
    )
    require(
        decision["action"]["destination"] == world["work_item_id"]
        and decision["action"]["adapter_id"] == "policy"
        and decision["action"]["adapter_version"] == "1.0.0",
        "DELIVERY_COMMITMENT_DECISION_ACTION",
        "binding",
    )
    require(
        decision["core_sdlc_trace_ref"]
        == sources["TRACE"]["trace_ref"]
        and sources["TRACE"]["work_item_id"] == world["work_item_id"]
        and sources["TRACE"]["current"] is True,
        "DELIVERY_COMMITMENT_TRACE",
        "",
    )
    require(
        sources["OWNER"]["authenticated"] is True,
        "DELIVERY_COMMITMENT_AUTHENTICATION",
        "",
    )
    auth_matches = [
        row
        for row in decision_source["authentication_contexts"]
        if row["authentication_context_id"]
        == decision["authentication_context_id"]
        and row["principal_id"] == decision["principal_id"]
        and row["current"] is True
    ]
    challenge_matches = [
        row
        for row in decision_source["presentation_challenges"]
        if row["presentation_challenge_digest"]
        == decision["presentation_challenge_digest"]
        and row["principal_id"] == decision["principal_id"]
        and row["current"] is True
    ]
    nonce_matches = [
        row
        for row in decision_source["nonces"]
        if row["nonce"] == decision["nonce"]
        and row["principal_id"] == decision["principal_id"]
        and row["current"] is True
        and row["use_count"] == 1
    ]
    require(
        len(auth_matches) == 1
        and len(challenge_matches) == 1
        and len(nonce_matches) == 1,
        "DELIVERY_COMMITMENT_AUTHENTICATION",
        "decision-bindings",
    )
    require(
        sources["OWNER"]["current"] is True
        and sources["OWNER"]["work_item_id"] == world["work_item_id"]
        and decision["principal_id"]
        == presented["commitment_owner_id"]
        == sources["OWNER"]["principal_id"],
        "DELIVERY_COMMITMENT_OWNER",
        "",
    )
    require(
        decision["scope"]
        == sorted(
            [
                world["work_item_id"],
                presented["plan_ref"],
                presented["scope_ref"],
            ],
            key=lambda value: value.encode("utf-8"),
        )
        and decision["conditions"]
        == ESTIMATE_COMMITMENT_TRIGGERS,
        "DELIVERY_COMMITMENT_TRIGGER_SET",
        "decision",
    )
    require(
        decision["revoked_at"] is None,
        "DELIVERY_COMMITMENT_DECISION_REVOKED",
        "",
    )
    require(
        observed_at
        < parse_utc_datetime(
            decision["expires_at"],
            "DELIVERY_COMMITMENT_DECISION_EXPIRED",
            "",
        ),
        "DELIVERY_COMMITMENT_DECISION_EXPIRED",
        "",
    )
    issued_at = parse_utc_datetime(
        decision["issued_at"],
        "DELIVERY_COMMITMENT_DECISION_CHRONOLOGY",
        "",
    )
    require(
        window_start <= issued_at < window_end
        and issued_at <= observed_at,
        "DELIVERY_COMMITMENT_DECISION_CHRONOLOGY",
        "",
    )
    require(
        decision["expires_at"]
        == presented["commitment_window_end"],
        "DELIVERY_COMMITMENT_DECISION_EXPIRED",
        "window",
    )
    superseding = [
        row
        for row in decisions
        if row.get("supersedes") == decision["decision_id"]
    ]
    require(
        not superseding,
        "DELIVERY_COMMITMENT_DECISION_SUPERSEDED",
        "",
    )
    if decision["supersedes"] is not None:
        require(
            any(
                row["decision_id"] == decision["supersedes"]
                and row["subject"]["subject_digest"]
                != decision["subject"]["subject_digest"]
                for row in decisions
            ),
            "DELIVERY_COMMITMENT_DECISION_SUPERSESSION",
            "",
        )
    overlapping = [
        row
        for row in decisions
        if row["decision_id"] != decision["decision_id"]
        and row.get("action", {}).get("destination")
        == world["work_item_id"]
        and row.get("expires_at") is not None
        and parse_utc_datetime(
            row["issued_at"],
            "DELIVERY_COMMITMENT_DECISION_OVERLAP",
            row["decision_id"],
        )
        < window_end
        and window_start
        < parse_utc_datetime(
            row["expires_at"],
            "DELIVERY_COMMITMENT_DECISION_OVERLAP",
            row["decision_id"],
        )
        and decision.get("supersedes") != row["decision_id"]
        and row.get("supersedes") != decision["decision_id"]
    ]
    require(
        not overlapping,
        "DELIVERY_COMMITMENT_DECISION_OVERLAP",
        ",".join(row["decision_id"] for row in overlapping),
    )
    require(
        not world["fired_recommit_triggers"],
        "DELIVERY_COMMITMENT_RECOMMIT_REQUIRED",
        ",".join(world["fired_recommit_triggers"]),
    )
    require(
        world["requested_authority"]
        == "DELIVERY_COMMITMENT_ONLY",
        "DELIVERY_COMMITMENT_AUTHORITY_BOUNDARY",
        world["requested_authority"],
    )
    require(
        decision["digest"] == digest(decision),
        "DELIVERY_COMMITMENT_DECISION_DIGEST",
        "",
    )
    artifact_matches = [
        row
        for row in decision_source["artifact_registry"]
        if row["artifact_ref"] == decision["decision_id"]
        and row["artifact_type"] == "human_decision"
        and row["artifact_digest"] == decision["digest"]
        and row["current"] is True
    ]
    require(
        len(artifact_matches) == 1,
        "DELIVERY_COMMITMENT_ARTIFACT_REGISTRY",
        decision["decision_id"],
    )
    decision_schema = schemas[
        contract["commitment_decision_role"]["schema_ref"]
    ]
    decision_errors = list(
        jsonschema.Draft202012Validator(
            decision_schema,
            format_checker=jsonschema.FormatChecker(),
        ).iter_errors(decision)
    )
    require(
        not decision_errors,
        "DELIVERY_COMMITMENT_DECISION_SCHEMA",
        decision_errors[0].message if decision_errors else "",
    )
    receipt = {
        "caller_id": caller_id,
        "result": "COMMITMENT_CURRENT",
        "authority_granted": True,
        "authority_scope": "DELIVERY_COMMITMENT_ONLY",
        "subject_ref": presented["subject_ref"],
        "subject_digest": expected_subject_digest,
        "decision_id": decision["decision_id"],
        "decision_digest": decision["digest"],
        "resolved_source_roles": copy.deepcopy(expected_roles),
    }
    world["caller_receipts"].append(receipt)
    return receipt


def evaluate_sdlc_pln_ready_exit(
    world: dict[str, Any],
    schemas: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    return resolve_estimate_commitment(
        world,
        schemas,
        caller_id="SDLC-PLN-001 READY exit evaluation",
    )


def query_delivery_commitment(
    world: dict[str, Any],
    schemas: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    return resolve_estimate_commitment(
        world,
        schemas,
        caller_id=(
            "any policy query that reports or relies on a delivery commitment"
        ),
    )


def resign_estimate_decision(
    decision: dict[str, Any],
    decision_source: dict[str, Any] | None = None,
) -> None:
    decision["digest"] = digest(decision)
    if decision_source is None:
        return
    matching = [
        row
        for row in decision_source["artifact_registry"]
        if row["artifact_ref"] == decision["decision_id"]
    ]
    if len(matching) == 1:
        matching[0]["artifact_digest"] = decision["digest"]


def apply_estimate_commitment_scenario(
    world: dict[str, Any],
    scenario: str,
) -> None:
    sources = world["sources"]
    decision_source = sources["DECISION"]
    decision = decision_source["records"][0]
    estimate = sources["ESTIMATE"]["observations"][0]
    if scenario == "estimate_only_remains_non_authoritative":
        world["query_kind"] = "ESTIMATE_ONLY"
        sources["DECISION"] = estimate_commitment_decision_source([])
    elif scenario == "exact_current_human_commitment_resolves":
        return
    elif (
        scenario
        == "fresh_recommitment_after_binding_change_resolves"
    ):
        old_decision = copy.deepcopy(decision)
        capacity = sources["CAPACITY"]
        capacity["ref"] += ":v2"
        capacity["digest"] = canonical_subject_digest(
            {
                key: value
                for key, value in capacity.items()
                if key not in {"digest", "current"}
            }
        )
        successor = copy.deepcopy(estimate)
        successor["estimate_id"] = "estimate_recommit"
        successor["supersedes_estimate_id"] = estimate["estimate_id"]
        successor["observed_at"] = "2026-07-28T00:00:00Z"
        successor["capacity_snapshot_ref"] = capacity["ref"]
        successor["capacity_snapshot_digest"] = capacity["digest"]
        successor["digest"] = digest(successor)
        sources["ESTIMATE"]["observations"].append(successor)
        world["bound_estimate_ids"] = [successor["estimate_id"]]
        world["prior_subjects"] = [
            copy.deepcopy(world["presented_subject"])
        ]
        world["presented_subject"] = estimate_commitment_subject(world)
        new_decision = estimate_commitment_decision(
            world["presented_subject"],
            decision_id="dec_estimate_commitment_recommit",
            supersedes=old_decision["decision_id"],
        )
        sources["DECISION"] = estimate_commitment_decision_source(
            [old_decision, new_decision]
        )
    elif scenario == "estimate_used_as_commitment":
        sources["DECISION"] = {
            "records": [copy.deepcopy(estimate)],
            "authentication_contexts": [],
            "presentation_challenges": [],
            "nonces": [],
            "artifact_registry": [],
        }
    elif scenario == "missing_commitment_decision":
        sources["DECISION"] = estimate_commitment_decision_source([])
    elif scenario == "wrong_commitment_subject_ref":
        decision["subject"]["subject_ref"] += ":wrong"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_commitment_subject_digest":
        decision["subject"]["subject_digest"] = "sha256:" + "0" * 64
        resign_estimate_decision(decision, decision_source)
    elif scenario == "cross_work_item_binding":
        estimate["work_item_id"] = "work_cross_subject"
        estimate["digest"] = digest(estimate)
    elif scenario == "stale_estimate_binding":
        successor = copy.deepcopy(estimate)
        successor["estimate_id"] = "estimate_successor"
        successor["supersedes_estimate_id"] = estimate["estimate_id"]
        successor["observed_at"] = "2026-07-28T00:00:00Z"
        successor["digest"] = digest(successor)
        sources["ESTIMATE"]["observations"].append(successor)
    elif scenario == "expired_estimate_binding":
        estimate["valid_until"] = "2026-07-28T12:00:00Z"
        estimate["digest"] = digest(estimate)
    elif scenario.startswith("stale_") and scenario.endswith(
        "_snapshot"
    ):
        role_by_scenario = {
            "stale_capacity_snapshot": "CAPACITY",
            "stale_dependency_snapshot": "DEPENDENCY",
            "stale_risk_snapshot": "RISK",
            "stale_acceptance_snapshot": "ACCEPTANCE",
        }
        sources[role_by_scenario[scenario]]["current"] = False
    elif scenario == "decision_status_not_approved":
        decision["status"] = "PENDING"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_decision_kind":
        decision["decision_kind"] = "EXCEPTION"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_decision_outcome":
        decision["outcome"] = "DENIED"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_decision_action":
        decision["action"]["action_type"] = "TRANSITION_WORK_ITEM"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_canonical_argument_digest":
        decision["action"]["canonical_argument_digest"] = (
            "sha256:" + "0" * 64
        )
        resign_estimate_decision(decision, decision_source)
    elif scenario == "wrong_core_sdlc_trace":
        decision["core_sdlc_trace_ref"] = "trace_other_work"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "expired_decision":
        decision["expires_at"] = "2026-07-28T12:00:00Z"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "revoked_decision":
        decision["revoked_at"] = "2026-07-28T12:00:00Z"
        resign_estimate_decision(decision, decision_source)
    elif scenario == "superseded_decision":
        superseding_subject = copy.deepcopy(
            world["presented_subject"]
        )
        superseding_subject["subject_ref"] += ":new"
        superseding = estimate_commitment_decision(
            superseding_subject,
            decision_id="dec_estimate_commitment_superseding",
            supersedes=decision["decision_id"],
        )
        sources["DECISION"] = estimate_commitment_decision_source(
            [decision, superseding]
        )
    elif scenario == "unauthenticated_decision":
        sources["OWNER"]["authenticated"] = False
    elif scenario == "wrong_commitment_owner":
        decision["principal_id"] = "principal_wrong_owner"
        for collection in (
            "authentication_contexts",
            "presentation_challenges",
            "nonces",
        ):
            decision_source[collection][0]["principal_id"] = (
                "principal_wrong_owner"
            )
        resign_estimate_decision(decision, decision_source)
    elif (
        scenario
        == "incomplete_or_mutated_recommit_trigger_set"
    ):
        world["presented_subject"]["recommit_trigger_ids"].pop()
    elif scenario == "changed_binding_without_fresh_recommitment":
        world["fired_recommit_triggers"] = ["CAPACITY_CHANGED"]
    elif scenario == "authority_escalation_attempt":
        world["requested_authority"] = "WORK_ITEM_STATE_TRANSITION"
    else:
        raise ContractFailure(
            "ESTIMATE_COMMITMENT_FIXTURE_SCENARIO_UNKNOWN:"
            + scenario
        )


def apply_estimate_commitment_invariant_mutation(
    world: dict[str, Any],
    mutation: str,
) -> None:
    sources = world["sources"]
    estimate = sources["ESTIMATE"]["observations"][0]
    method_rows = sources["ESTIMATE"]["methods"]
    evidence_rows = sources["ESTIMATE"]["evidence"]
    decision_source = sources["DECISION"]
    decision = decision_source["records"][0]
    if mutation == "future_estimate":
        estimate["observed_at"] = "2026-07-30T00:00:00Z"
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_subject_schema":
        estimate["subject_schema"] = "work-item-scope/v2"
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_subject_ref":
        estimate["subject_ref"] += ":unknown"
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_subject_digest":
        estimate["subject_digest"] = "sha256:" + "0" * 64
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_subject_wrong_work_item":
        scope = sources["SCOPE"]
        scope["work_item_id"] = "work_other"
        scope["digest"] = canonical_subject_digest(
            {
                key: value
                for key, value in scope.items()
                if key not in {"digest", "current"}
            }
        )
        estimate["subject_digest"] = scope["digest"]
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_subject_stale":
        sources["SCOPE"]["current"] = False
    elif mutation == "estimate_method_unknown":
        estimate["method_ref"] = "urn:ranex:estimate-method:unknown"
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_method_wrong_version":
        method_rows[0]["method_version"] = "2.0.0"
    elif mutation == "estimate_method_stale":
        method_rows[0]["current"] = False
    elif mutation == "estimate_method_wrong_subject":
        method_rows[0]["work_item_id"] = "work_other"
    elif mutation == "estimate_method_schema":
        method_rows[0]["method_schema"] = "estimate-method/v2"
    elif mutation == "estimate_method_digest":
        method_rows[0]["digest"] = "sha256:" + "0" * 64
    elif mutation == "estimate_method_duplicate":
        method_rows.append(copy.deepcopy(method_rows[0]))
    elif mutation == "estimate_method_omitted":
        method_rows.clear()
    elif mutation == "estimate_method_non_independent":
        method_rows[0]["independently_governed"] = False
    elif mutation == "estimate_evidence_unknown":
        estimate["evidence_bindings"][0]["evidence_ref"] += ":unknown"
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_evidence_wrong_version":
        evidence_rows[0]["evidence_version"] = "2.0.0"
    elif mutation == "estimate_evidence_stale":
        evidence_rows[0]["current"] = False
    elif mutation == "estimate_evidence_wrong_subject":
        evidence_rows[0]["work_item_id"] = "work_other"
    elif mutation == "estimate_evidence_schema":
        evidence_rows[0]["evidence_schema"] = "estimate-evidence/v2"
    elif mutation == "estimate_evidence_digest":
        evidence_rows[0]["digest"] = "sha256:" + "0" * 64
    elif mutation == "estimate_evidence_binding_digest":
        estimate["evidence_bindings"][0]["evidence_digest"] = (
            "sha256:" + "0" * 64
        )
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_evidence_duplicate":
        evidence_rows.append(copy.deepcopy(evidence_rows[0]))
    elif mutation == "estimate_evidence_omitted":
        evidence_rows.clear()
    elif mutation == "estimate_evidence_binding_duplicate":
        estimate["evidence_bindings"].append(
            copy.deepcopy(estimate["evidence_bindings"][0])
        )
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_scope_binding":
        estimate["subject_digest"] = "sha256:" + "0" * 64
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_capacity_binding":
        estimate["capacity_snapshot_digest"] = "sha256:" + "0" * 64
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_dependency_binding":
        estimate["dependency_snapshot_digest"] = "sha256:" + "0" * 64
        estimate["digest"] = digest(estimate)
    elif mutation == "commitment_window_order":
        world["presented_subject"]["commitment_window_start"] = (
            world["presented_subject"]["commitment_window_end"]
        )
    elif mutation == "decision_issued_chronology":
        decision["issued_at"] = "2026-07-27T00:00:00Z"
        resign_estimate_decision(decision, decision_source)
    elif mutation == "duplicate_exact_decision":
        duplicate = estimate_commitment_decision(
            world["presented_subject"],
            decision_id="dec_estimate_commitment_duplicate",
        )
        sources["DECISION"] = estimate_commitment_decision_source(
            [decision, duplicate]
        )
    elif mutation == "overlapping_decision":
        alternate_subject = copy.deepcopy(
            world["presented_subject"]
        )
        alternate_subject["subject_ref"] += ":alternate"
        alternate = estimate_commitment_decision(
            alternate_subject,
            decision_id="dec_estimate_commitment_overlap",
        )
        sources["DECISION"] = estimate_commitment_decision_source(
            [decision, alternate]
        )
    elif mutation == "authentication_context_stale":
        decision_source["authentication_contexts"][0][
            "current"
        ] = False
    elif mutation == "presentation_challenge_wrong":
        decision["presentation_challenge_digest"] = (
            "sha256:" + "0" * 64
        )
        resign_estimate_decision(decision, decision_source)
    elif mutation == "nonce_reused":
        decision_source["nonces"][0]["use_count"] = 2
    elif mutation == "artifact_registry_missing":
        decision_source["artifact_registry"] = []
    elif mutation == "query_kind_unknown":
        world["query_kind"] = "BEST_EFFORT"
    elif mutation == "supersession_chronology":
        successor = copy.deepcopy(estimate)
        successor["estimate_id"] = "estimate_bad_chronology"
        successor["supersedes_estimate_id"] = estimate["estimate_id"]
        successor["observed_at"] = estimate["observed_at"]
        successor["digest"] = digest(successor)
        sources["ESTIMATE"]["observations"].append(successor)
    elif mutation == "decision_digest_drift":
        decision["digest"] = "sha256:" + "0" * 64
        decision_source["artifact_registry"][0][
            "artifact_digest"
        ] = decision["digest"]
    elif mutation == "estimate_digest_drift":
        estimate["digest"] = "sha256:" + "0" * 64
    elif mutation == "estimate_range_invalid":
        estimate["lower_bound"] = 10
        estimate["digest"] = digest(estimate)
    elif mutation == "estimate_time_invalid":
        estimate["observed_at"] = estimate["valid_until"]
        estimate["digest"] = digest(estimate)
    elif mutation == "plan_not_current":
        sources["PLAN"]["current"] = False
    elif mutation == "scope_not_current":
        sources["SCOPE"]["current"] = False
    elif mutation == "trace_not_current":
        sources["TRACE"]["current"] = False
    else:
        raise ContractFailure(
            "ESTIMATE_COMMITMENT_INVARIANT_MUTATION_UNKNOWN:"
            + mutation
        )


def validate_estimate_commitment_schema_matrix(
    schemas: dict[str, dict[str, Any]],
    checks: Counter[str],
) -> None:
    contract = estimate_commitment_machine_contract()
    world = build_estimate_commitment_world()
    samples = {
        "EstimateObservationV1": world["sources"]["ESTIMATE"][
            "observations"
        ][0],
        "DELIVERY_COMMITMENT_SUBJECT_V1": world[
            "presented_subject"
        ],
    }
    source_rows = {
        "EstimateObservationV1": contract["estimate_record"],
        "DELIVERY_COMMITMENT_SUBJECT_V1": contract[
            "commitment_subject_projection"
        ],
    }
    schema_by_type = {
        type_id: schemas[row["schema_ref"]]
        for type_id, row in source_rows.items()
    }
    invalid_values = [None, {}, [], False, "", -1]
    for type_id, sample in samples.items():
        schema = schema_by_type[type_id]
        validator = jsonschema.Draft202012Validator(
            schema,
            format_checker=jsonschema.FormatChecker(),
        )
        require(
            validator.is_valid(sample),
            "ESTIMATE_COMMITMENT_SCHEMA_POSITIVE",
            type_id,
        )
        checks["estimate_commitment_schema_positive_cases"] += 1
        fields = source_rows[type_id][
            "fields"
            if type_id == "EstimateObservationV1"
            else "output_fields"
        ]
        require(
            set(schema["required"]) == set(fields)
            and set(schema["properties"]) == set(fields)
            and schema["additionalProperties"] is False,
            "ESTIMATE_COMMITMENT_SCHEMA_SOURCE_BINDING",
            type_id,
        )
        for field_name in fields:
            omitted = copy.deepcopy(sample)
            del omitted[field_name]
            require(
                not validator.is_valid(omitted),
                "ESTIMATE_COMMITMENT_SCHEMA_OMISSION_ACCEPTED",
                f"{type_id}:{field_name}",
            )
            checks[
                "estimate_commitment_schema_omission_cases"
            ] += 1
            require(
                any(
                    not validator.is_valid(
                        {
                            **copy.deepcopy(sample),
                            field_name: candidate,
                        }
                    )
                    for candidate in invalid_values
                ),
                "ESTIMATE_COMMITMENT_SCHEMA_WRONG_TYPE_UNPROVEN",
                f"{type_id}:{field_name}",
            )
            checks[
                "estimate_commitment_schema_wrong_type_cases"
            ] += 1
        additional = {
            **copy.deepcopy(sample),
            "undeclared_field": True,
        }
        require(
            not validator.is_valid(additional),
            "ESTIMATE_COMMITMENT_SCHEMA_ADDITIONAL_ACCEPTED",
            type_id,
        )
        checks[
            "estimate_commitment_schema_additional_cases"
        ] += 1
    status_injection = copy.deepcopy(
        samples["EstimateObservationV1"]
    )
    status_injection["status"] = "CURRENT"
    status_errors = list(
        jsonschema.Draft202012Validator(
            schema_by_type["EstimateObservationV1"]
        ).iter_errors(status_injection)
    )
    require(
        any(
            error.validator == "additionalProperties"
            for error in status_errors
        ),
        "ESTIMATE_MUTABLE_STATUS_INJECTION_ACCEPTED",
        "",
    )
    checks["estimate_mutable_status_injection_cases"] += 1
    estimate_fields = len(
        contract["estimate_record"]["fields"]
    )
    subject_fields = len(
        contract["commitment_subject_projection"]["output_fields"]
    )
    require(
        checks["estimate_commitment_schema_positive_cases"] == 2
        and checks["estimate_commitment_schema_omission_cases"]
        == estimate_fields + subject_fields
        and checks["estimate_commitment_schema_wrong_type_cases"]
        == estimate_fields + subject_fields
        and checks["estimate_commitment_schema_additional_cases"]
        == 2
        and checks["estimate_mutable_status_injection_cases"] == 1,
        "ESTIMATE_COMMITMENT_SCHEMA_MATRIX_COUNTS",
        "",
    )


def validate_estimate_commitment_projection_registry(
    checks: Counter[str],
) -> None:
    contract = estimate_commitment_machine_contract()
    projection_contract = contract["contract_projection_contract"]
    registry = load_json(
        ROOT / contract["contract_projection_ref"]
    )

    def projection_errors(candidate: Any) -> set[str]:
        if not isinstance(candidate, dict):
            return {"SHAPE"}
        errors: set[str] = set()
        if set(candidate) != set(
            projection_contract["envelope_fields"]
        ):
            errors.add("FIELD_ORDER_OR_SET")
        if (
            candidate.get("registry_id")
            != contract["contract_projection_id"]
            or candidate.get("version") != contract["contract_version"]
            or candidate.get("status")
            != "DEFINED_RUNTIME_NOT_ASSESSED"
            or candidate.get("source_path")
            != "docs/architecture/SDLC_CONTROL_CATALOG.md"
            or candidate.get("source_fragment")
            != "SDLC ESTIMATE COMMITMENT CONTROL"
            or candidate.get("source_digest")
            != "sha256:" + ESTIMATE_COMMITMENT_BLOCK_SHA256
            or candidate.get("generated_by")
            != "scripts/architecture/generate_contracts.py"
        ):
            errors.add("METADATA")
        if candidate.get("entries") != [contract]:
            errors.add("SOURCE_PROJECTION")
        return errors

    require(
        not projection_errors(registry),
        "ESTIMATE_COMMITMENT_PROJECTION_REGISTRY",
        "",
    )
    checks["estimate_commitment_projection_entries"] += 1
    mutations: list[tuple[str, dict[str, Any], str]] = []
    missing = copy.deepcopy(registry)
    del missing["entries"]
    mutations.append(("missing", missing, "FIELD_ORDER_OR_SET"))
    additional = copy.deepcopy(registry)
    additional["undeclared"] = True
    mutations.append(
        ("additional", additional, "FIELD_ORDER_OR_SET")
    )
    wrong_digest = copy.deepcopy(registry)
    wrong_digest["source_digest"] = "sha256:" + "0" * 64
    mutations.append(("digest", wrong_digest, "METADATA"))
    forged_entry = copy.deepcopy(registry)
    forged_entry["entries"][0]["control_id"] = "SDLC-FORGED-001"
    mutations.append(
        ("source", forged_entry, "SOURCE_PROJECTION")
    )
    for mutation, candidate, expected in mutations:
        require(
            expected in projection_errors(candidate),
            "ESTIMATE_COMMITMENT_PROJECTION_NEGATIVE_ACCEPTED",
            mutation,
        )
        checks[
            "estimate_commitment_projection_negative_cases"
        ] += 1
    require(
        checks["estimate_commitment_projection_negative_cases"]
        == 4,
        "ESTIMATE_COMMITMENT_PROJECTION_NEGATIVE_COUNTS",
        "",
    )


def validate_estimate_commitment_v2_definition_coverage(
    schemas: dict[str, dict[str, Any]],
    checks: Counter[str],
) -> None:
    """Validate the V2 declarations without claiming resolver execution."""

    contract = estimate_commitment_machine_contract()
    authority = contract["source_authority_contract"]

    registry_shapes = {
        row["type_id"]: row for row in authority["registry_shapes"]
    }
    role_authorities = {
        row["registry_type"]: row
        for row in authority["role_authorities"]
    }

    def source_invariants(row: dict[str, Any]) -> list[str]:
        plural = row.get("invariants")
        if plural is not None:
            return copy.deepcopy(plural)
        singular = row.get("invariant")
        return (
            [singular]
            if isinstance(singular, str) and singular
            else []
        )

    common_history_invariant = authority[
        "common_closed_registry_fields"
    ]["invariant"]

    def registry_invariants(row: dict[str, Any]) -> list[str]:
        if set(row.get("field_types", {})) == set(row["fields"]):
            return source_invariants(row)
        return [common_history_invariant, *source_invariants(row)]

    expected_rows: dict[
        str,
        tuple[str, list[str], bool, list[str]],
    ] = {
        contract["estimate_record"]["schema_ref"]: (
            contract["estimate_record"]["type_id"],
            contract["estimate_record"]["fields"],
            False,
            source_invariants(contract["estimate_record"]),
        ),
        contract["commitment_subject_projection"]["schema_ref"]: (
            contract["commitment_subject_projection"][
                "projection_id"
            ],
            contract["commitment_subject_projection"][
                "output_fields"
            ],
            False,
            source_invariants(
                contract["commitment_subject_projection"]
            ),
        ),
        authority["source_envelope"]["schema_ref"]: (
            authority["source_envelope"]["type_id"],
            authority["source_envelope"]["fields"],
            True,
            source_invariants(authority["source_envelope"]),
        ),
        authority["source_trust_registry_shape"]["schema_ref"]: (
            authority["source_trust_registry_shape"]["type_id"],
            authority["source_trust_registry_shape"]["fields"],
            True,
            registry_invariants(
                authority["source_trust_registry_shape"]
            ),
        ),
    }
    for row in authority["record_types"]:
        expected_rows[row["schema_ref"]] = (
            row["type_id"],
            row["fields"],
            True,
            source_invariants(row),
        )
    for registry_type, role in role_authorities.items():
        shape = registry_shapes[registry_type]
        expected_rows[role["schema_ref"]] = (
            registry_type,
            shape["fields"],
            True,
            registry_invariants(shape),
        )
    require(
        len(expected_rows) == 33,
        "ESTIMATE_V2_SCHEMA_DECLARATION_DENOMINATOR",
        str(len(expected_rows)),
    )

    observed_type_ids: set[str] = set()
    observed_invariants_by_type: dict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)

    def collect_type_ids(value: Any) -> None:
        if isinstance(value, dict):
            type_id = value.get("x-ranex-type-id")
            if isinstance(type_id, str):
                observed_type_ids.add(type_id)
                invariants = value.get(
                    "x-ranex-semantic-invariants"
                )
                require(
                    isinstance(invariants, list)
                    and all(
                        isinstance(item, str) and item
                        for item in invariants
                    ),
                    "ESTIMATE_V2_SCHEMA_INVARIANT_SHAPE",
                    type_id,
                )
                observed_invariants_by_type[type_id].add(
                    tuple(invariants)
                )
            for nested in value.values():
                collect_type_ids(nested)
        elif isinstance(value, list):
            for nested in value:
                collect_type_ids(nested)

    def require_closed_objects(value: Any, path: str) -> None:
        if isinstance(value, dict):
            if value.get("type") == "object":
                properties = value.get("properties")
                require(
                    isinstance(properties, dict)
                    and value.get("additionalProperties") is False
                    and set(value.get("required", []))
                    == set(properties),
                    "ESTIMATE_V2_SCHEMA_OBJECT_NOT_CLOSED",
                    path,
                )
            for key, nested in value.items():
                require_closed_objects(nested, path + "/" + key)
        elif isinstance(value, list):
            for index, nested in enumerate(value):
                require_closed_objects(
                    nested,
                    path + "/" + str(index),
                )

    for schema_ref, (
        type_id,
        fields,
        is_source_authority,
        expected_invariants,
    ) in expected_rows.items():
        schema = schemas.get(schema_ref)
        require(
            isinstance(schema, dict),
            "ESTIMATE_V2_SCHEMA_MISSING",
            schema_ref,
        )
        require(
            schema.get("x-ranex-source-contract-id")
            == contract["contract_id"]
            and schema.get("x-ranex-source-control-id")
            == contract["control_id"]
            and (
                not is_source_authority
                or schema.get(
                    "x-ranex-source-authority-contract-id"
                )
                == authority["source_contract_id"]
            )
            and schema.get("x-ranex-type-id") == type_id
            and schema.get("type") == "object"
            and schema.get("additionalProperties") is False
            and schema.get("required") == fields
            and set(schema.get("properties", {})) == set(fields)
            and schema.get("x-ranex-semantic-invariants")
            == expected_invariants,
            "ESTIMATE_V2_SCHEMA_SOURCE_BINDING",
            schema_ref,
        )
        require_closed_objects(schema, schema_ref)
        collect_type_ids(schema)
        checks["estimate_v2_declared_schema_documents"] += 1
    require(
        checks["estimate_v2_declared_schema_documents"] == 33,
        "ESTIMATE_V2_SCHEMA_DECLARATION_COUNTS",
        "",
    )

    expected_embedded_types = {
        row["type_id"] for row in contract["nested_types"]
    } | {
        authority["sources_object"]["type_id"],
        *[
            row["type_id"]
            for row in authority["record_types"]
        ],
        *registry_shapes,
        authority["source_trust_registry_shape"]["type_id"],
        contract["estimate_record"]["type_id"],
        contract["commitment_subject_projection"]["projection_id"],
        authority["source_envelope"]["type_id"],
    }
    require(
        expected_embedded_types <= observed_type_ids,
        "ESTIMATE_V2_SCHEMA_EMBEDDED_TYPE_COVERAGE",
        ",".join(sorted(expected_embedded_types - observed_type_ids)),
    )
    expected_invariants_by_type = {
        row["type_id"]: source_invariants(row)
        for row in contract["nested_types"]
    } | {
        row["type_id"]: source_invariants(row)
        for row in authority["record_types"]
    } | {
        type_id: registry_invariants(row)
        for type_id, row in registry_shapes.items()
    } | {
        authority["source_trust_registry_shape"]["type_id"]:
            registry_invariants(
                authority["source_trust_registry_shape"]
            ),
        authority["sources_object"]["type_id"]:
            source_invariants(authority["sources_object"]),
        contract["estimate_record"]["type_id"]:
            source_invariants(contract["estimate_record"]),
        contract["commitment_subject_projection"]["projection_id"]:
            source_invariants(
                contract["commitment_subject_projection"]
            ),
        authority["source_envelope"]["type_id"]:
            source_invariants(authority["source_envelope"]),
    }
    for type_id, expected_invariants in (
        expected_invariants_by_type.items()
    ):
        require(
            observed_invariants_by_type.get(type_id)
            == {tuple(expected_invariants)},
            "ESTIMATE_V2_SCHEMA_INVARIANT_SOURCE_BINDING",
            type_id,
        )
        checks["estimate_v2_declared_invariant_bindings"] += 1
    checks["estimate_v2_declared_embedded_types"] = len(
        expected_embedded_types
    )

    fixture = contract["fixture_contract"]
    expected_suite_fields = {
        "fixture_suite",
        "contract_id",
        "coverage_status",
        "semantic_execution_count",
        "schema_matrix_status",
        "runtime_validation_status",
        "cases",
    }
    expected_case_fields = {
        "case_id",
        "source_envelope_version",
        "query_kind",
        "mutation",
        "expected_result",
        "expected_failure_code",
        "expected_authority_effects",
    }
    suites = (
        (
            load_json(ROOT / fixture["positive_fixture_ref"]),
            fixture["positive_suite_id"],
            fixture["positive_case_ids"],
            True,
        ),
        (
            load_json(ROOT / fixture["negative_fixture_ref"]),
            fixture["negative_suite_id"],
            [
                case_id
                for rows in fixture[
                    "negative_case_ids_by_boundary"
                ].values()
                for case_id in rows
            ],
            False,
        ),
    )
    for suite, suite_id, raw_expected_ids, positive in suites:
        expected_ids = sorted(
            raw_expected_ids,
            key=lambda value: value.encode("utf-8"),
        )
        cases = suite.get("cases", [])
        actual_ids = [
            row.get("case_id")
            for row in cases
            if isinstance(row, dict)
        ]
        require(
            set(suite) == expected_suite_fields
            and suite.get("fixture_suite") == suite_id
            and suite.get("contract_id") == contract["contract_id"]
            and suite.get("coverage_status")
            == "DECLARED_DEFINITION_COVERAGE_NOT_EXECUTED"
            and suite.get("semantic_execution_count") == 0
            and suite.get("schema_matrix_status") == "NOT_EXECUTED"
            and suite.get("runtime_validation_status")
            == "NOT_ASSESSED"
            and len(cases) == len(expected_ids)
            and actual_ids == expected_ids,
            "ESTIMATE_V2_FIXTURE_DECLARATION_SET",
            suite_id,
        )
        for row in cases:
            require(
                set(row) == expected_case_fields
                and row["source_envelope_version"] == "2.0.0"
                and row["query_kind"]
                in {"ESTIMATE_ONLY", "COMMITMENT"}
                and (
                    (
                        positive
                        and row["mutation"] == "NONE"
                        and row["expected_failure_code"] is None
                        and row["expected_authority_effects"]
                        in [
                            [],
                            ["DELIVERY_COMMITMENT_FACT_ONLY"],
                        ]
                    )
                    or (
                        not positive
                        and row["mutation"] == row["case_id"]
                        and row["expected_result"]
                        == "REJECTED_ZERO_AUTHORITY"
                        and row["expected_failure_code"]
                        == row["case_id"]
                        and row["expected_authority_effects"] == []
                    )
                ),
                "ESTIMATE_V2_FIXTURE_DECLARATION_SHAPE",
                str(row.get("case_id")),
            )
        checks[
            (
                "estimate_v2_declared_positive_cases"
                if positive
                else "estimate_v2_declared_negative_cases"
            )
        ] = len(cases)
    require(
        checks["estimate_v2_declared_positive_cases"] == 6
        and checks["estimate_v2_declared_negative_cases"] == 213,
        "ESTIMATE_V2_FIXTURE_DECLARATION_COUNTS",
        "",
    )
    checks["estimate_v2_semantic_execution_cases"] = 0
    checks["estimate_v2_schema_matrix_execution_cases"] = 0
    checks["estimate_v2_runtime_validation_not_assessed"] += 1


def validate_estimate_commitment_caller_paths(
    schemas: dict[str, dict[str, Any]],
    checks: Counter[str],
) -> None:
    source_tree = ast.parse(
        Path(__file__).read_text(encoding="utf-8")
    )
    caller_names = {
        "evaluate_sdlc_pln_ready_exit",
        "query_delivery_commitment",
    }
    functions = {
        node.name: node
        for node in source_tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name in caller_names
    }
    require(
        set(functions) == caller_names,
        "ESTIMATE_COMMITMENT_CALLER_SET",
        "",
    )
    for name, function in functions.items():
        calls = [
            node
            for node in ast.walk(function)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "resolve_estimate_commitment"
        ]
        require(
            len(function.body) == 1
            and isinstance(function.body[0], ast.Return)
            and len(calls) == 1
            and not function.args.defaults
            and not function.args.kw_defaults,
            "ESTIMATE_COMMITMENT_CALLER_BYPASS",
            name,
        )
        checks["estimate_commitment_mandatory_callers"] += 1
    runtime_world = build_estimate_commitment_world()
    first = evaluate_sdlc_pln_ready_exit(
        runtime_world,
        schemas,
    )
    second = query_delivery_commitment(
        runtime_world,
        schemas,
    )
    require(
        [first["caller_id"], second["caller_id"]]
        == estimate_commitment_machine_contract()[
            "resolver_contract"
        ]["production_callers"]
        and all(
            receipt["result"] == "COMMITMENT_CURRENT"
            and receipt["authority_scope"]
            == "DELIVERY_COMMITMENT_ONLY"
            for receipt in (first, second)
        ),
        "ESTIMATE_COMMITMENT_CALLER_RECEIPT",
        "",
    )
    checks["estimate_commitment_caller_receipts"] += 2


